<?php
declare(strict_types=1);
require_once __DIR__.'/Orders.php';
require_once __DIR__.'/CheckoutBundles.php';
require_once __DIR__.'/HotelPayments.php';
final class PaymentTargets
{
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    public function state(string $code):array
    {
        if(!$this->db->inTransaction())throw new LogicException('Payment state requires a transaction.');if(str_starts_with($code,'JH')){$hotel=(new HotelPayments($this->db))->locked($code);return ['orders'=>[],'cart'=>null,'bundle'=>null,'hotel'=>$hotel,'amount'=>$hotel['total'],'locale'=>$hotel['data']['locale']??'vi'];}
        if(str_starts_with($code,'JB')){$b=$this->query('SELECT id FROM jingo_checkout_bundles WHERE code=?',[$code])->fetchColumn();if(!$b)throw new HttpError(404,'Không tìm thấy mã tổng.');$s=(new CheckoutBundles($this->db))->gatewayState($b);$d=json_decode($s['bundle']['data'],true,512,JSON_THROW_ON_ERROR);return ['orders'=>$s['orders'],'cart'=>$s['cart'],'bundle'=>$s['bundle'],'amount'=>$s['total'],'locale'=>$d['locale']??'vi'];}
        $cart=null;if(str_starts_with($code,'JC')){$cart=$this->query('SELECT * FROM jingo_carts WHERE code=? FOR UPDATE',[$code])->fetch(PDO::FETCH_ASSOC);if(!$cart||$cart['channel']!=='WEB')throw new HttpError(404,'Không tìm thấy giỏ web.');CheckoutLinks::guard($this->db,'cartId',$cart['id']);$rows=$this->query('SELECT o.* FROM jingo_cart_orders m JOIN jingo_orders o ON o.id=m.order_id WHERE m.cart_id=? ORDER BY o.id FOR UPDATE',[$cart['id']])->fetchAll(PDO::FETCH_ASSOC);$orders=[];foreach($rows as $r)if($r['booking_status']==='CONFIRMED'&&$r['payment_status']==='UNPAID'&&!$this->query('SELECT order_id FROM jingo_order_archives WHERE order_id=?',[$r['id']])->fetchColumn())$orders[]=$r;}else{$r=$this->query('SELECT * FROM jingo_orders WHERE code=? FOR UPDATE',[$code])->fetch(PDO::FETCH_ASSOC);if(!$r)throw new HttpError(404,'Không tìm thấy đơn.');if($this->query('SELECT cart_id FROM jingo_cart_orders WHERE order_id=?',[$r['id']])->fetchColumn())throw new HttpError(409,'Mở giỏ JC để thanh toán nhiều gói.');CheckoutLinks::guard($this->db,'orderId',$r['id']);$orders=[$r];}
        if(!$orders)throw new HttpError(409,'Không còn khoản chưa thanh toán.');$amount=0;foreach($orders as $r){if($r['booking_status']!=='CONFIRMED'||$r['payment_status']!=='UNPAID'||$this->query('SELECT order_id FROM jingo_order_archives WHERE order_id=?',[$r['id']])->fetchColumn()||$this->query('SELECT order_id FROM jingo_pos_orders WHERE order_id=?',[$r['id']])->fetchColumn()||$this->query('SELECT order_id FROM jingo_partner_orders WHERE order_id=?',[$r['id']])->fetchColumn())throw new HttpError(409,'Chỉ thanh toán đơn web đã xác nhận, chưa thu tiền và còn hiệu lực.');$s=json_decode($r['snapshot'],true,512,JSON_THROW_ON_ERROR);if(!is_int($s['total'])||$s['total']<0)throw new HttpError(409,'Giá đơn không hợp lệ.');$amount+=$s['total'];}if($amount<1||$amount>15000000000)throw new HttpError(409,'Tổng thanh toán từ 1 đến 15 tỷ.');return ['orders'=>$orders,'cart'=>$cart,'bundle'=>null,'amount'=>$amount,'locale'=>json_decode($orders[0]['snapshot'],true,512,JSON_THROW_ON_ERROR)['locale']??'vi'];
    }
    private function authorize(array $state,array $in):void
    {
        $row=$state['bundle']?:($state['cart']?:$state['orders'][0]);$key=$in['accessKey']??null;if($key!==null){if(!hash_equals($row['access_hash'],hash('sha256',$key)))throw new HttpError(404,'Không tìm thấy đơn.');return;}if($state['bundle']||!isset($in['email']))throw new HttpError(404,'Không tìm thấy đơn.');$contact=json_decode($state['orders'][0]['contact'],true,512,JSON_THROW_ON_ERROR);if(strcasecmp(trim($contact['email']),trim($in['email']))!==0)throw new HttpError(404,'Không tìm thấy đơn.');
    }
    public function authorizeCode(array $in):void
    {
        $cart=null;$bundle=null;$orders=[];$code=$in['code'];if(str_starts_with($code,'JH')){(new HotelPayments($this->db))->authorize($code,$in);return;}if(str_starts_with($code,'JB')){$bundle=$this->query('SELECT * FROM jingo_checkout_bundles WHERE code=?',[$code])->fetch(PDO::FETCH_ASSOC);if(!$bundle)throw new HttpError(404,'Không tìm thấy đơn.');}elseif(str_starts_with($code,'JC')){$cart=$this->query('SELECT * FROM jingo_carts WHERE code=?',[$code])->fetch(PDO::FETCH_ASSOC);if(!$cart||$cart['channel']!=='WEB')throw new HttpError(404,'Không tìm thấy đơn.');$orders=$this->query('SELECT o.* FROM jingo_cart_orders m JOIN jingo_orders o ON o.id=m.order_id WHERE m.cart_id=? ORDER BY o.id LIMIT 1',[$cart['id']])->fetchAll(PDO::FETCH_ASSOC);if(!$orders)throw new HttpError(404,'Không tìm thấy đơn.');}else{$row=$this->query('SELECT * FROM jingo_orders WHERE code=?',[$code])->fetch(PDO::FETCH_ASSOC);if(!$row)throw new HttpError(404,'Không tìm thấy đơn.');$orders=[$row];}$this->authorize(compact('bundle','cart','orders'),$in);
    }
    public function credit(array $s,string $reference,string $provider,?string $reconciliationActor=null):void
    {
        if(!$this->db->inTransaction()||!in_array($provider,['VNPAY','SEPAY'],true)||!str_starts_with($reference,$provider.':LIVE:'))throw new LogicException('Invalid gateway credit context.');$method=$reconciliationActor===null?$provider:'BANK';$actor=$reconciliationActor??'gateway:'.$provider;if($reconciliationActor!==null&&($provider!=='SEPAY'||$actor===''||str_starts_with($actor,'gateway:')))throw new LogicException('Invalid reconciliation actor.');if(isset($s['hotel'])){(new HotelPayments($this->db))->credit($s['hotel'],$reference,$provider,$reconciliationActor);return;}if($s['bundle']){(new CheckoutBundles($this->db))->collect(['code'=>$s['bundle']['code'],'expectedTotal'=>$s['amount'],'verified'=>true,'collectionMethod'=>$method],'gateway:'.$provider,true,$reference,$reconciliationActor);return;}if($s['cart'])$this->query("INSERT INTO jingo_payment_references(reference_hash,reference,kind,entity_id,amount) VALUES (?,?,'CART_PAYMENT',?,?)",[hash('sha256',$reference),$reference,$s['cart']['id'],$s['amount']]);$orders=new Orders($this->db);foreach($s['orders'] as $o){$ref=$s['cart']?$reference.'#'.$o['code']:$reference;$orders->act($o['id'],['requestId'=>self::uuid(),'action'=>'PAY','version'=>(int)$o['version'],'amount'=>json_decode($o['snapshot'],true,512,JSON_THROW_ON_ERROR)['total'],'method'=>'BANK','reference'=>$ref,'note'=>($reconciliationActor===null?'Tự xác nhận ':'Đối soát ').$reference],$actor,null,true);$this->query("UPDATE jingo_order_payments SET method=? WHERE order_id=? AND reference_hash=?",[$method,$o['id'],hash('sha256',$ref)]);if(!$s['cart'])OrderMail::enqueue($this->db,$o['id'],'PAY',(int)$o['version']+1);}if($s['cart']){$this->query('UPDATE jingo_carts SET version=version+1 WHERE id=?',[$s['cart']['id']]);OrderMail::enqueue($this->db,$s['orders'][0]['id'],'CART_PAY',(int)$s['orders'][0]['version']+1);}
    }
    private static function uuid():string{$h=bin2hex(random_bytes(16));return substr($h,0,8).'-'.substr($h,8,4).'-4'.substr($h,13,3).'-8'.substr($h,17,3).'-'.substr($h,20);}
}
